/*                                                                        */
/*    This file defines a minimal module-port shim for the Linux/GNU      */
/*    simulation target.  It exists solely to allow the module manager    */
/*    sources to be compiled and tested on Linux without requiring a      */
/*    hardware-specific MPU or dispatch layer.  It does not implement     */
/*    memory protection or the privileged dispatcher; those features are  */
/*    only available on real embedded targets.                            */
/*                                                                        */
/**************************************************************************/

#ifndef TXM_MODULE_PORT_H
#define TXM_MODULE_PORT_H

/* !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
 * WARNING — TEST SCAFFOLD ONLY: NO MEMORY ISOLATION IS ENFORCED
 * !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
 *
 * This port header is a MINIMAL SHIM that allows the module manager sources
 * to compile and run on Linux/x86-64 for unit-testing purposes.
 *
 * It does NOT provide:
 *   - Memory isolation between module and kernel (no mprotect/MPU enforcement)
 *   - A privileged dispatcher gate (no SVC/SVCall equivalent)
 *   - Module binary loading from filesystem images
 *   - Bounds checking on module-to-kernel pointer parameters
 *
 * All TXM_MODULE_MANAGER_PARAM_CHECK_* macros unconditionally return TX_TRUE.
 * A module running under this port has FULL READ/WRITE ACCESS to the entire
 * process address space, including all kernel objects and data structures.
 * Any isolation breach will result in SILENT MEMORY CORRUPTION, not a fault.
 *
 * DO NOT use this port as a security boundary or to validate isolation.
 * It is suitable ONLY for testing module manager logic (object lifecycle,
 * dispatch routing, error paths) on Linux development machines and in CI.
 *
 * A mprotect()-based isolation implementation that replaces this scaffold
 * is tracked at: https://github.com/eclipse-threadx/threadx/issues/557
 * !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
 */

/* Include optional user-defined module configuration.  */
#ifdef TXM_MODULE_INCLUDE_USER_DEFINE_FILE
#include "txm_module_user.h"
#endif

/* ---- Thread extension ------------------------------------------------- */
/* tx_port.h for the Linux/GNU port already defines TX_THREAD_EXTENSION_2
   as "VOID *tx_thread_module_instance_ptr;" which is sufficient for the
   module manager to store and retrieve the owning module instance.  The
   remaining fields present in embedded module ports (MPU region registers,
   kernel-stack base/size, etc.) are not needed for simulation testing.   */


/* ---- Module property flags -------------------------------------------- */
#define TXM_MODULE_USER_MODE                        0x00000001UL
#define TXM_MODULE_MEMORY_PROTECTION                0x00000002UL
#define TXM_MODULE_SHARED_EXTERNAL_MEMORY_ACCESS    0x00000004UL

#define TXM_MODULE_MANAGER_SUPPORTED_OPTIONS        (TXM_MODULE_USER_MODE)
#define TXM_MODULE_MANAGER_REQUIRED_OPTIONS         0U


/* ---- Module heap and kernel-stack sizes ------------------------------- */
#ifndef TXM_MODULE_HEAP_SIZE
#define TXM_MODULE_HEAP_SIZE    512U
#endif

#ifndef TXM_MODULE_KERNEL_STACK_SIZE
#define TXM_MODULE_KERNEL_STACK_SIZE    768U
#endif


/* ---- Parameter-check and object-check macros -------------------------- */
/* On embedded ports these macros validate that a pointer lies within the
   module's MPU-protected data region.  On the Linux simulation we simply
   accept the pointer so that the module manager sources compile cleanly.  */

#define TXM_MODULE_MANAGER_PARAM_CHECK_OBJECT_FOR_USE(mi, ptr, size) \
    (TX_TRUE)

#define TXM_MODULE_MANAGER_PARAM_CHECK_OBJECT_FOR_CREATION(mi, ptr, size) \
    (TX_TRUE)

#define TXM_MODULE_MANAGER_PARAM_CHECK_BUFFER_WRITE(mi, ptr, size) \
    (TX_TRUE)

#define TXM_MODULE_MANAGER_PARAM_CHECK_BUFFER_READ(mi, ptr, size) \
    (TX_TRUE)


/* ---- Module-load callback (no-op on Linux simulation) ----------------- */
#define TXM_MODULE_MANAGER_MODULE_SETUP(mi)
#define TXM_MODULE_MANAGER_MODULE_UNLOAD(mi)


/* ---- Module instance port extension (none needed for Linux sim) ------- */
/* On embedded ports this adds MPU-register arrays to TXM_MODULE_INSTANCE.
   The Linux simulation does not implement memory protection, so the
   extension is empty.  */
#define TXM_MODULE_MANAGER_PORT_EXTENSION


/* ---- Additional manager prototypes (none for Linux sim) --------------- */
/* Embedded ports declare hardware-specific helpers here (MPU setup, fault
   handler, etc.).  None of those are needed for the Linux simulation.    */
#define TXM_MODULE_MANAGER_ADDITIONAL_PROTOTYPES


/* ---- Version identity string ------------------------------------------ */
#define TXM_MODULE_MANAGER_VERSION_ID   \
CHAR _txm_module_manager_version_id[] = \
    "Copyright (c) 2026 Eclipse ThreadX contributors.  *  ThreadX Module Linux Simulation Version 6.5.2.202603 *";


#endif /* TXM_MODULE_PORT_H */
